// @vitest-environment happy-dom
/// <reference types="node" />
import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { describe, expect, it, vi } from "vitest";

vi.mock("@tauri-apps/api/core", () => ({ invoke: vi.fn() }));
vi.mock("@tauri-apps/api/event", () => ({ listen: vi.fn() }));

import type { Folder, NoteMeta } from "./ipc";
import {
  linkAttachments,
  markdownFileName,
  noteToMarkdown,
  splitPath,
  workspaceExportFiles,
} from "./markdown";

// Generated by BlockNote (scripts/make-fixture.mjs); shared with the Rust tests.
const fixture = new Uint8Array(
  readFileSync(
    resolve(__dirname, "../../../../crates/ichnote-core/tests/fixtures/blocknote-note.bin"),
  ),
);

const note = (over: Partial<NoteMeta>): NoteMeta => ({
  id: "n",
  workspaceId: "w",
  title: "",
  folderId: null,
  pinned: false,
  inInbox: false,
  createdAt: 0,
  updatedAt: 0,
  deletedAt: null,
  ...over,
});

describe("markdown export", () => {
  it("converts BlockNote content with the title as heading", () => {
    const md = noteToMarkdown("Shopping", fixture);
    expect(md.startsWith("# Shopping\n\n# Grocery list\n")).toBe(true);
    expect(md).toContain("Buy **fresh** café beans");
    expect(md).toContain("[x] Milk");
    expect(md).toContain("```rust\nfn main() {}\n```");
  });

  it("handles an empty note", () => {
    expect(noteToMarkdown("", new Uint8Array())).toBe("\n");
  });

  it("names files and splits paths", () => {
    expect(markdownFileName(" a/b ")).toBe("a-b.md");
    expect(markdownFileName("")).toBe("Untitled.md");
    expect(splitPath("/Users/me/Notes/x.md")).toEqual({ dir: "/Users/me/Notes", name: "x.md" });
    expect(splitPath("C:\\Notes\\x.md")).toEqual({ dir: "C:\\Notes", name: "x.md" });
  });

  it("puts notes in folder directories and skips trashed notes", () => {
    const folders: Folder[] = [
      { id: "f", name: "Work", parentId: null, createdAt: 0, deletedAt: null },
    ];
    const files = workspaceExportFiles(
      [
        note({ id: "a", title: "Plan", folderId: "f" }),
        note({ id: "b", title: "Loose", folderId: "gone" }),
        note({ id: "c", title: "Old", deletedAt: 1 }),
      ],
      folders,
      new Map([["a", fixture]]),
      "Ichnote export",
    );
    expect(files.map((f) => f.path)).toEqual([
      "Ichnote export/Work/Plan.md",
      "Ichnote export/Loose.md",
    ]);
  });

  it("links attachments relative to each exported file", () => {
    const id = "01a1f183-155a-742b-8142-8bf1bb30173e";
    const att = {
      id,
      workspaceId: "w",
      hash: "h",
      name: "cat.png",
      mime: "image/png",
      size: 1,
      createdAt: 0,
    };
    const md = `![cat](ichnote-attachment:${id})`;
    const { files, copies } = linkAttachments(
      [
        { path: "Export/Top.md", contents: md },
        { path: "Export/Work/Deep.md", contents: md },
      ],
      [att],
      "Export",
    );
    expect(files[0]?.contents).toBe("![cat](attachments/bb30173e-cat.png)");
    expect(files[1]?.contents).toBe("![cat](../attachments/bb30173e-cat.png)");
    expect(copies).toEqual([{ id, path: "Export/attachments/bb30173e-cat.png" }]);
    const single = linkAttachments([{ path: "Note.md", contents: md }], [att], "");
    expect(single.files[0]?.contents).toBe("![cat](attachments/bb30173e-cat.png)");
    expect(single.copies[0]?.path).toBe("attachments/bb30173e-cat.png");
  });
});
